gorseller = {0: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" width="100%" height="100%">\n  <defs>\n    <linearGradient id="bg_mat1" x1="0%" y1="0%" x2="100%" y2="100%">\n      <stop offset="0%" stop-color="#eef2ff"/>\n      <stop offset="100%" stop-color="#e0e7ff"/>\n    </linearGradient>\n  </defs>\n  <rect width="100%" height="100%" fill="url(#bg_mat1)" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="bold" fill="#312e81">Üstel ve Logaritmik Denklem Çözüm Yolları</text>\n  <g transform="translate(25, 45)">\n    <rect x="0" y="0" width="165" height="65" rx="6" fill="#ffffff" stroke="#a5b4fc" stroke-width="1.5"/>\n    <text x="82" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#4338ca">Taban Eşitleme</text>\n    <text x="82" y="45" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#312e81">aᶠ⁽ˣ⁾ = aᵍ⁽ˣ⁾ ⇔ f(x)=g(x)</text>\n  </g>\n  <g transform="translate(210, 45)">\n    <rect x="0" y="0" width="165" height="65" rx="6" fill="#ffffff" stroke="#a5b4fc" stroke-width="1.5"/>\n    <text x="82" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#4338ca">Logaritma Alma</text>\n    <text x="82" y="45" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#312e81">aˣ = b ⇔ x = logₐb</text>\n  </g>\n  <g transform="translate(25, 125)">\n    <rect x="0" y="0" width="165" height="65" rx="6" fill="#ffffff" stroke="#a5b4fc" stroke-width="1.5"/>\n    <text x="82" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#4338ca">Değişken Dönüşümü</text>\n    <text x="82" y="45" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#312e81">t = aˣ ile 2. derece</text>\n  </g>\n  <g transform="translate(210, 125)">\n    <rect x="0" y="0" width="165" height="65" rx="6" fill="#ffffff" stroke="#a5b4fc" stroke-width="1.5"/>\n    <text x="82" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#4338ca">Tanım Kümesi</text>\n    <text x="82" y="45" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#312e81">Taban &gt; 0, ≠ 1 ve İç &gt; 0</text>\n  </g>\n</svg>', 1: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#f8fafc" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#0f172a">Taban Eşitleme: 3²ˣ⁻¹ = 27 Çözümü</text>\n  <g transform="translate(60, 45)">\n    <rect x="0" y="0" width="280" height="85" rx="6" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>\n    <text x="140" y="28" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#334155">3²ˣ⁻¹ = 3³</text>\n    <text x="140" y="50" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#334155">Tabanlar eşit ⇒ 2x - 1 = 3</text>\n    <text x="140" y="72" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#4f46e5">2x = 4 ⇒ x = 2</text>\n  </g>\n</svg>', 2: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#f5f3ff" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#5b21b6">Logaritmik Denklem: log₂(x - 3) = 4</text>\n  <g transform="translate(60, 45)">\n    <rect x="0" y="0" width="280" height="85" rx="6" fill="#ffffff" stroke="#c4b5fd" stroke-width="1.5"/>\n    <text x="140" y="28" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#6d28d9">Tanım Kümesi: x - 3 &gt; 0 ⇒ x &gt; 3</text>\n    <text x="140" y="50" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#334155">x - 3 = 2⁴ = 16</text>\n    <text x="140" y="72" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#6d28d9">x = 19 ∈ Ç.K.</text>\n  </g>\n</svg>', 3: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#f1f5f9" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#0f172a">Logaritmik Eşitsizlikte Taban Kuralı</text>\n  <g transform="translate(40, 50)">\n    <rect x="0" y="0" width="140" height="85" rx="6" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n    <text x="70" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#16a34a">a &gt; 1 (Artan)</text>\n    <text x="70" y="50" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#334155">logₐf(x) &lt; logₐg(x)</text>\n    <text x="70" y="70" text-anchor="middle" font-family="sans-serif" font-size="10" font-weight="bold" fill="#15803d">f(x) &lt; g(x) (Yön Aynen)</text>\n  </g>\n  <g transform="translate(220, 50)">\n    <rect x="0" y="0" width="140" height="85" rx="6" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n    <text x="70" y="25" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#dc2626">0 &lt; a &lt; 1 (Azalan)</text>\n    <text x="70" y="50" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#334155">logₐf(x) &lt; logₐg(x)</text>\n    <text x="70" y="70" text-anchor="middle" font-family="sans-serif" font-size="10" font-weight="bold" fill="#b91c1c">f(x) &gt; g(x) (Yön Değişir)</text>\n  </g>\n</svg>', 5: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 190" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#eef2ff" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#312e81">log₃(2x - 1) ≤ 2 Eşitsizliğinin Çözüm Adımları</text>\n  <g transform="translate(30, 45)">\n    <circle cx="30" cy="40" r="15" fill="#4f46e5"/>\n    <text x="30" y="44" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">1</text>\n    <text x="30" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#312e81">Tanım: 2x-1&gt;0</text>\n    <circle cx="105" cy="40" r="15" fill="#4338ca"/>\n    <text x="105" y="44" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">2</text>\n    <text x="105" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#312e81">Taban 3&gt;1</text>\n    <circle cx="180" cy="40" r="15" fill="#3730a3"/>\n    <text x="180" y="44" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">3</text>\n    <text x="180" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#312e81">2x-1 ≤ 3²=9</text>\n    <circle cx="255" cy="40" r="15" fill="#312e81"/>\n    <text x="255" y="44" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">4</text>\n    <text x="255" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#312e81">x ≤ 5</text>\n    <circle cx="330" cy="40" r="15" fill="#16a34a"/>\n    <text x="330" y="44" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">5</text>\n    <text x="330" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#15803d">(1/2, 5]</text>\n  </g>\n</svg>', 6: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#fef2f2" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#991b1b">Taban 1/2 Olduğunda Eşitsizlik Yön Değişimi</text>\n  <g transform="translate(60, 45)">\n    <rect x="0" y="0" width="280" height="85" rx="6" fill="#ffffff" stroke="#fca5a5" stroke-width="1.5"/>\n    <text x="140" y="28" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#334155">log₁/₂(x - 1) &gt; -2</text>\n    <text x="140" y="50" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#dc2626">Taban 0 &lt; 1/2 &lt; 1 ⇒ x - 1 &lt; (1/2)⁻² = 4</text>\n    <text x="140" y="72" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="bold" fill="#991b1b">x &gt; 1 ve x &lt; 5 ⇒ Ç.K. = (1, 5)</text>\n  </g>\n</svg>', 8: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#f8fafc" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#0f172a">Özdeşlik ve Değişken Değiştirme Kuralı</text>\n  <g transform="translate(60, 50)">\n    <rect x="0" y="0" width="280" height="70" rx="8" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>\n    <text x="140" y="30" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#2563eb">4ˣ - 3·2ˣ - 4 = 0</text>\n    <text x="140" y="55" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#475569">t = 2ˣ dönüşümü ile t² - 3t - 4 = 0</text>\n  </g>\n</svg>', 10: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#eef2ff" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#312e81">Matematik Terimleri İpuçları (Şifre: TABAN)</text>\n  <g transform="translate(60, 45)">\n    <rect x="0" y="0" width="50" height="50" rx="6" fill="#4f46e5"/>\n    <text x="25" y="32" text-anchor="middle" font-family="sans-serif" font-size="18" font-weight="bold" fill="#ffffff">T</text>\n    <text x="25" y="65" text-anchor="middle" font-family="sans-serif" font-size="9" fill="#3730a3">Teğet</text>\n    <rect x="60" y="0" width="50" height="50" rx="6" fill="#4f46e5"/>\n    <text x="85" y="32" text-anchor="middle" font-family="sans-serif" font-size="18" font-weight="bold" fill="#ffffff">A</text>\n    <text x="85" y="65" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#3730a3">Asimptot</text>\n    <rect x="120" y="0" width="50" height="50" rx="6" fill="#4f46e5"/>\n    <text x="145" y="32" text-anchor="middle" font-family="sans-serif" font-size="18" font-weight="bold" fill="#ffffff">B</text>\n    <text x="145" y="65" text-anchor="middle" font-family="sans-serif" font-size="9" fill="#3730a3">Bağıntı</text>\n    <rect x="180" y="0" width="50" height="50" rx="6" fill="#4f46e5"/>\n    <text x="205" y="32" text-anchor="middle" font-family="sans-serif" font-size="18" font-weight="bold" fill="#ffffff">A</text>\n    <text x="205" y="65" text-anchor="middle" font-family="sans-serif" font-size="9" fill="#3730a3">Aralık</text>\n    <rect x="240" y="0" width="50" height="50" rx="6" fill="#4f46e5"/>\n    <text x="265" y="32" text-anchor="middle" font-family="sans-serif" font-size="18" font-weight="bold" fill="#ffffff">N</text>\n    <text x="265" y="65" text-anchor="middle" font-family="sans-serif" font-size="9" fill="#3730a3">Nokta</text>\n  </g>\n</svg>'}


def uygula(o):
    s = o.get("sorular", [])
    for idx, svg in gorseller.items():
        if int(idx) < len(s):
            s[int(idx)]["gorsel"] = svg
